tasks.solution:
public class Main {
    public static void main(String[] args) {
        int boxes = 6;
        int stock = 0;
        // 두 조건의 순서를 바꿔 stock이 0이면 나눗셈을 하지 않게 하세요.
        // &&는 왼쪽이 거짓이면 오른쪽을 계산하지 않아요. 0 검사를 왼쪽에 둬요.
        boolean enough = stock > 0 && boxes / stock > 1;
        System.out.println(enough);
    }
}

