        int last = 5;
        int skip = 3;
        int total = 0;
        for (int item = 1; item <= last; item++) {
            // 이 주석 아래에 item이 skip과 같으면 이번 회차만 건너뛰는 줄을 쓰세요.
            total += item;
        }
        System.out.println(total);
    }
}

tasks.solution:
public class Main {
    public static void main(String[] args) {
        int last = 5;
        int skip = 3;
        int total = 0;
        for (int item = 1; item <= last; item++) {
            // 이 주석 아래에 item이 skip과 같으면 이번 회차만 건너뛰는 줄을 쓰세요.
            // continue는 아래 total += item을 건너뛰고 다음 item으로 가요. break라면 반복을 끝내요.
            if (item == skip) continue;
            total += item;
        }
        System.out.println(total);
    }
}

