tasks.example_code:
class Counter {
    // 양수 재고를 묶음 두 개로 계산해요.
    static int twice(int value) { return value * 2; }
}

public class Main {
    public static void main(String[] args) {
        int[] stocks = {2, 0, 3};
        int total = 0;
        for (int stock : stocks) {
            // 양수만 두 배로 세어요.
            if (stock > 0) total += Counter.twice(stock);
        }
        System.out.println(total);
    }
}

